// รับคำสั่งจากผู้ดูแล/ระบบอื่น: { mode:'preview'|'apply', period?, reason? }
// ตัวอย่างเรียก:  curl -X POST http://localhost:5679/webhook/net-1x5/run -H 'Content-Type: application/json' -d '{"mode":"preview"}'
const b = ($json.body && typeof $json.body === 'object') ? $json.body : ($json || {});
const mode = (b.mode === 'apply') ? 'apply' : 'preview';
const period = (typeof b.period === 'string' && /^\d{4}-\d{2}$/.test(b.period)) ? b.period : undefined;
const body = { mode: mode };
if (period) body.period = period;
body.idempotencyKey = 'net1x5-webhook-' + mode + '-' + new Date().toISOString().slice(0, 19).replace(/[:T]/g, '');
return [{ json: { mode: mode, period: period || null, reason: b.reason || null, requestBody: body, requestedAt: new Date().toISOString() } }];

// สรุปผล + เตรียมส่งกลับให้ผู้เรียก
const r = $json || {};
const sm = r.summary || {};
return [{ json: {
  ok: r.ok !== false,
  mode: r.mode || null,
  runId: r.runId || null,
  period: r.period || null,
  deadline: (r.deadline || {}).label || null,
  summary: sm,
  failed: r.failed || [],
  promotions: r.promotions || [],
  vacancies: r.vacancies || [],
  candidates: (r.candidates || []).slice(0, 20),
  warnings: r.warnings || [],
  note: 'ทุกการเปลี่ยนแปลงถูกบันทึกใน Audit Log ตรวจสอบย้อนหลังได้',
  finishedAt: new Date().toISOString()
} }];
